#include <iostream>
#include <fstream>
using namespace std;

bool czyPierwsza(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) return false;
    }
    return true;
}

int sumaKwCyfr(int n) {
    int suma = 0;
    while (n > 0) {
        int c = n % 10;
        suma += c * c;
        n /= 10;
    }
    return suma;
}

int main() {
    ifstream plik("dane.txt");
    int n;
    int ile = 0;
    while (plik >> n) {
        int s = sumaKwCyfr(n);
        bool p = czyPierwsza(s);
        cout << n << ": suma kwadratow cyfr = " << s << ", pierwsza: " << (p ? "TAK" : "NIE") << endl;
        if (p) ile++;
    }
    cout << "Liczb z pierwsza suma kwadratow cyfr: " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: Laczymy dwie operacje: (1) sumowanie kwadratow cyfr zamiast samych cyfr, (2) test pierwszosci wyniku.

